INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation) SELECT artifact.source_work_id,artifact.source_artifact_id,'heading','Environments and Hazards > Vacuum Exposure',CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Environments and Hazards: Vacuum Exposure' ELSE 'Cepheus Engine v9.1, Environments and Hazards: Vacuum Exposure' END FROM src_artifact artifact JOIN src_work work USING(source_work_id) WHERE artifact.source_uri IN('src/book3/environments-and-hazards.md','https://cepheus-srd.opengamingnetwork.com/cepheus-engine-srd/cepheus-engine-environments-and-hazards/') ON CONFLICT DO NOTHING;
WITH package AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'environment.vacuum','Vacuum Exposure','other','approved','Vacuum composes airless suffocation and high irradiated-area exposure; beginning on round three, Very Difficult Endurance checks resist aeroembolism, stunning, and exceptional-failure unconsciousness.' FROM package;
CREATE TABLE rule_vacuum_exposure(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),first_check_round_offset smallint NOT NULL CHECK(first_check_round_offset=2),difficulty_rule_id bigint NOT NULL REFERENCES rule_difficulty(rule_id),resistance_characteristic_rule_id bigint NOT NULL REFERENCES rule_characteristic(rule_id),exceptional_failure_effect_max smallint NOT NULL CHECK(exceptional_failure_effect_max=-6),failure_stuns boolean NOT NULL CHECK(failure_stuns),stun_blocks_general_movement boolean NOT NULL CHECK(stun_blocks_general_movement),stun_ends_at_normal_pressure boolean NOT NULL CHECK(stun_ends_at_normal_pressure),suffocation_profile_id bigint NOT NULL REFERENCES rule_suffocation_profile(suffocation_profile_id),radiation_source_profile_id bigint NOT NULL REFERENCES rule_radiation_source_profile(radiation_source_profile_id));
INSERT INTO rule_vacuum_exposure SELECT vacuum.rule_id,2,difficulty.rule_id,endurance.rule_id,-6,true,true,true,suffocation.suffocation_profile_id,radiation.radiation_source_profile_id FROM rule_rule vacuum CROSS JOIN rule_rule difficulty CROSS JOIN rule_rule endurance CROSS JOIN rule_suffocation_profile suffocation CROSS JOIN rule_radiation_source_profile radiation WHERE vacuum.rule_code='environment.vacuum' AND difficulty.rule_code='difficulty.very-difficult' AND endurance.rule_code='characteristic.endurance' AND suffocation.exposure_code='utterly-airless' AND radiation.source_code='irradiated-high';
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT rule.rule_id,rule.content_package_id,locator.source_locator_id,CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'direct' ELSE 'corroborating' END,work.work_code='cepheus-engine.ogn' FROM rule_rule rule CROSS JOIN src_locator locator JOIN src_work work USING(source_work_id) WHERE rule.rule_code='environment.vacuum' AND locator.heading_path='Environments and Hazards > Vacuum Exposure' AND work.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');
CREATE TABLE env_vacuum_episode(vacuum_episode_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,actor_id bigint NOT NULL,campaign_id bigint NOT NULL,encounter_id bigint NOT NULL REFERENCES enc_personal_combat(encounter_id),began_combat_round integer NOT NULL CHECK(began_combat_round>0),suffocation_episode_id bigint NOT NULL UNIQUE REFERENCES env_suffocation_episode(suffocation_episode_id),radiation_source_profile_id bigint NOT NULL REFERENCES rule_radiation_source_profile(radiation_source_profile_id),episode_status text NOT NULL DEFAULT 'active' CHECK(episode_status IN('active','pressure-restored')),checks_completed integer NOT NULL DEFAULT 0 CHECK(checks_completed>=0),last_check_round integer,stunned boolean NOT NULL DEFAULT false,unconscious boolean NOT NULL DEFAULT false,concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),CHECK((episode_status='active')=(resolved_at IS NULL)),CHECK(NOT unconscious OR stunned));
CREATE UNIQUE INDEX env_one_active_vacuum_episode ON env_vacuum_episode(actor_id) WHERE episode_status='active';
CREATE TABLE env_vacuum_check_receipt(vacuum_check_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,vacuum_episode_id bigint NOT NULL REFERENCES env_vacuum_episode(vacuum_episode_id),check_sequence integer NOT NULL CHECK(check_sequence>0),combat_round integer NOT NULL CHECK(combat_round>0),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),task_succeeded boolean NOT NULL,exceptional_failure boolean NOT NULL,stunned_before boolean NOT NULL,stunned_after boolean NOT NULL,unconscious_before boolean NOT NULL,unconscious_after boolean NOT NULL,episode_version_before bigint NOT NULL,episode_version_after bigint NOT NULL CHECK(episode_version_after=episode_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(vacuum_episode_id,combat_round),UNIQUE(vacuum_episode_id,check_sequence));
CREATE TABLE env_vacuum_pressure_restoration_receipt(vacuum_pressure_restoration_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,vacuum_episode_id bigint NOT NULL UNIQUE REFERENCES env_vacuum_episode(vacuum_episode_id),suffocation_relief_receipt_id bigint NOT NULL UNIQUE REFERENCES env_suffocation_relief_receipt(suffocation_relief_receipt_id),episode_version_before bigint NOT NULL,episode_version_after bigint NOT NULL CHECK(episode_version_after=episode_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION env_validate_vacuum_episode() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE air env_suffocation_episode%ROWTYPE;rule rule_vacuum_exposure%ROWTYPE;BEGIN SELECT * INTO STRICT air FROM env_suffocation_episode WHERE suffocation_episode_id=NEW.suffocation_episode_id;SELECT * INTO STRICT rule FROM rule_vacuum_exposure;IF air.actor_id<>NEW.actor_id OR air.encounter_id<>NEW.encounter_id OR air.began_combat_round<>NEW.began_combat_round OR air.suffocation_profile_id<>rule.suffocation_profile_id OR NEW.radiation_source_profile_id<>rule.radiation_source_profile_id THEN RAISE EXCEPTION 'Vacuum episode must compose matching airless suffocation and high irradiated-area profiles' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER env_vacuum_episode_valid BEFORE INSERT ON env_vacuum_episode FOR EACH ROW EXECUTE FUNCTION env_validate_vacuum_episode();
CREATE FUNCTION env_finalize_vacuum_check() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE episode env_vacuum_episode%ROWTYPE;rule rule_vacuum_exposure%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;BEGIN SELECT * INTO STRICT episode FROM env_vacuum_episode WHERE vacuum_episode_id=NEW.vacuum_episode_id FOR UPDATE;SELECT * INTO STRICT rule FROM rule_vacuum_exposure;SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;IF episode.episode_status<>'active' OR NEW.combat_round<episode.began_combat_round+rule.first_check_round_offset OR NEW.combat_round<>(SELECT current_round FROM enc_personal_combat WHERE encounter_id=episode.encounter_id) OR (episode.last_check_round IS NOT NULL AND NEW.combat_round<=episode.last_check_round) OR NEW.check_sequence<>episode.checks_completed+1 OR NEW.episode_version_before<>episode.concurrency_version OR task.actor_id<>episode.actor_id OR task.characteristic_rule_id<>rule.resistance_characteristic_rule_id OR task.skill_rule_id IS NOT NULL OR task.difficulty_rule_id<>rule.difficulty_rule_id OR task.circumstance_modifier<>0 OR NEW.task_succeeded<>task.succeeded OR NEW.exceptional_failure<>(NOT task.succeeded AND task.effect<=rule.exceptional_failure_effect_max) OR NEW.stunned_before<>episode.stunned OR NEW.unconscious_before<>episode.unconscious OR NEW.stunned_after<>(episode.stunned OR NOT task.succeeded) OR NEW.unconscious_after<>(episode.unconscious OR NEW.exceptional_failure) THEN RAISE EXCEPTION 'Vacuum check must match round-three timing, Very Difficult Endurance task, effect, conditions, sequence, and version' USING ERRCODE='23514';END IF;UPDATE env_vacuum_episode SET checks_completed=NEW.check_sequence,last_check_round=NEW.combat_round,stunned=NEW.stunned_after,unconscious=NEW.unconscious_after,concurrency_version=NEW.episode_version_after WHERE vacuum_episode_id=episode.vacuum_episode_id;RETURN NEW;END $$;CREATE TRIGGER env_vacuum_check_final BEFORE INSERT ON env_vacuum_check_receipt FOR EACH ROW EXECUTE FUNCTION env_finalize_vacuum_check();
CREATE FUNCTION env_finalize_vacuum_restoration() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE episode env_vacuum_episode%ROWTYPE;relief env_suffocation_relief_receipt%ROWTYPE;BEGIN SELECT * INTO STRICT episode FROM env_vacuum_episode WHERE vacuum_episode_id=NEW.vacuum_episode_id FOR UPDATE;SELECT * INTO STRICT relief FROM env_suffocation_relief_receipt WHERE suffocation_relief_receipt_id=NEW.suffocation_relief_receipt_id;IF episode.episode_status<>'active' OR relief.suffocation_episode_id<>episode.suffocation_episode_id OR NEW.episode_version_before<>episode.concurrency_version THEN RAISE EXCEPTION 'Pressure restoration must close the linked airless episode and current vacuum version' USING ERRCODE='23514';END IF;UPDATE env_vacuum_episode SET episode_status='pressure-restored',stunned=false,unconscious=false,resolved_at=NEW.recorded_at,concurrency_version=NEW.episode_version_after WHERE vacuum_episode_id=episode.vacuum_episode_id;RETURN NEW;END $$;CREATE TRIGGER env_vacuum_restoration_final BEFORE INSERT ON env_vacuum_pressure_restoration_receipt FOR EACH ROW EXECUTE FUNCTION env_finalize_vacuum_restoration();
CREATE FUNCTION env_reject_vacuum_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Vacuum checks and restoration history are immutable';END $$;CREATE TRIGGER env_vacuum_check_immutable BEFORE UPDATE OR DELETE ON env_vacuum_check_receipt FOR EACH ROW EXECUTE FUNCTION env_reject_vacuum_mutation();CREATE TRIGGER env_vacuum_restoration_immutable BEFORE UPDATE OR DELETE ON env_vacuum_pressure_restoration_receipt FOR EACH ROW EXECUTE FUNCTION env_reject_vacuum_mutation();CREATE FUNCTION env_guard_vacuum_state() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Vacuum state changes require immutable check or restoration receipts' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER env_vacuum_episode_guard BEFORE UPDATE OR DELETE ON env_vacuum_episode FOR EACH ROW EXECUTE FUNCTION env_guard_vacuum_state();
